coverage.content:
// Covergroup Declaration Style — MANDATORY STRUCTURE
// The covergroup is declared INSIDE the class body (not inside any function).
// It must be instantiated in the constructor: cover_group = new;
// It is sampled in the run_phase via cover_group.sample();
//
// covergroup name convention: <DUT_name>_cover_group
// coverpoint name convention: cp_<signal_name>
// cross name convention:      cross_<A>_<B>

   covergroup <DUT_name>_cover_group;

      option.per_instance = 1;                          // separate stats per instance
      option.goal         = 100;                        // target 100% coverage
      option.comment      = "<DUT_name> Functional Coverage";

      // ── Input Signal Coverpoints ──────────────────────────────────────
      cp_<input_signal_1>: coverpoint sequence_item.<input_signal_1> {
         bins <signal>_inactive = {0};
         bins <signal>_active   = {1};
      }

      // ── Output / Status Signal Coverpoints ───────────────────────────
      cp_<output_flag>: coverpoint sequence_item.<output_flag> {
         bins <flag>_inactive = {0};
         bins <flag>_active   = {1};
      }

      // ── Cross Coverage ────────────────────────────────────────────────
      cross_<A>_<B>: cross cp_<input_signal_1>, cp_<output_flag>;

   endgroup : <DUT_name>_cover_group

// Coverage Class Structure Style
// Coverage collector extends uvm_component.
// Include TLM analysis exports to receive transactions from monitors.
// The covergroup is declared as a class member (not inside any function).

class <DUT_name>_coverage extends uvm_component;
    `uvm_component_utils(<DUT_name>_coverage)

    // Define analysis export & tlm_fifo
       uvm_analysis_export   #(<DUT_name>_sequence_item) Seq_export ;
       uvm_tlm_analysis_fifo #(<DUT_name>_sequence_item) fifo       ;

    // sequence_item handle (used inside covergroup)
       <DUT_name>_sequence_item sequence_item;

    // covergroup declaration (inside class, outside any function)
       covergroup <DUT_name>_cover_group;
          // ... coverpoints and crosses go here ...
       endgroup : <DUT_name>_cover_group

    // covergroup handle
       <DUT_name>_cover_group cover_group;

// Binary Coverpoint Style — for 1-bit signals
// Always define explicit bins for 0 and 1 to track both active and inactive states.
// Use for: rst_n, write_en, read_en, valid_in, push, pop, flush, start, enable, etc.

        // <Signal Name> Coverage
           cp_<signal_name>: coverpoint sequence_item.<signal_name> {
            bins <signal>_inactive = {0};
            bins <signal>_active   = {1};
           }

// Small Multi-bit Coverpoint Style (2-4 bits) — enumerate EVERY value explicitly
// Use for: opcodes (2-3 bits), small counters, state encodings, small enums.
// Explicitly define bins for boundary values (0, max) AND all intermediate values.

        // Usage Coverage (e.g. 3-bit counter 0..7)
           cp_<multibit_signal>: coverpoint sequence_item.<multibit_signal> {
             bins <signal>_min      = {0};       // minimum / empty / idle
             bins <signal>_low      = {[1:2]};   // low range
             bins <signal>_mid      = {[3:5]};   // mid range
             bins <signal>_high     = {[6:<MAX>-1]}; // high range
             bins <signal>_max      = {<MAX>};   // maximum / full / saturated
           }

// Wide Data Bus Coverpoint Style (8-bit and above) — use range bins
// NEVER enumerate every value for wide signals — use ranges instead.
// Divide the value space into meaningful zones: zero, low, mid, high, max.
// Use for: data_in[7:0], data_in[31:0], result[15:0], payload, etc.

        // 8-bit Data Coverage
           cp_<data_signal>: coverpoint sequence_item.<data_signal> {
             bins <signal>_zero     = {8'h00};              // all zeros
             bins <signal>_low      = {[8'h01 : 8'h3F]};   // 1..63   (lower quarter)
             bins <signal>_mid      = {[8'h40 : 8'hBF]};   // 64..191 (middle half)
             bins <signal>_high     = {[8'hC0 : 8'hFE]};   // 192..254 (upper quarter)
             bins <signal>_max      = {8'hFF};              // all ones
           }

        // 32-bit Data Coverage (same pattern, larger ranges)
           cp_<data32_signal>: coverpoint sequence_item.<data32_signal> {
             bins <signal>_zero     = {32'h0000_0000};
             bins <signal>_low      = {[32'h0000_0001 : 32'h3FFF_FFFF]};
             bins <signal>_mid      = {[32'h4000_0000 : 32'hBFFF_FFFF]};
             bins <signal>_high     = {[32'hC000_0000 : 32'hFFFF_FFFE]};
             bins <signal>_max      = {32'hFFFF_FFFF};
           }

// Transition Bins Style — for FSM state signals or sequential protocol signals
// Use transition bins to verify that specific state-to-state transitions actually occur.
// Syntax: bins <name> = (<from_val> => <to_val>);
// Use for: UART states (IDLE->START->DATA->PARITY->STOP),
//          SPI phases, handshake sequences, any FSM state register.

        // FSM State Transitions Coverage
           cp_<state_signal>: coverpoint sequence_item.<state_signal> {
             // Individual state coverage
             bins state_IDLE    = {0};
             bins state_START   = {1};
             bins state_DATA    = {2};
             bins state_PARITY  = {3};
             bins state_STOP    = {4};

             // Transition coverage — critical legal sequences
             bins trans_idle_to_start  = (0 => 1);  // IDLE -> START
             bins trans_start_to_data  = (1 => 2);  // START -> DATA
             bins trans_data_to_parity = (2 => 3);  // DATA -> PARITY
             bins trans_parity_to_stop = (3 => 4);  // PARITY -> STOP
             bins trans_stop_to_idle   = (4 => 0);  // STOP -> IDLE (frame complete)

             // Illegal direct transitions (should never happen)
             illegal_bins illegal_idle_to_data  = (0 => 2);  // skip START
             illegal_bins illegal_idle_to_stop  = (0 => 4);  // skip to STOP
           }

// Cross Coverage Style
// Cross coverpoints that are logically correlated to verify edge cases.
// Best crosses: control_signal X status_flag, opcode X valid, write X full, read X empty.

        // Cross: write enable with full flag (catch write-when-full scenario)
           cross_<write>_<full>: cross cp_<write_en>, cp_<full_flag>;

        // Cross: read enable with empty flag (catch read-when-empty scenario)
           cross_<read>_<empty>: cross cp_<read_en>, cp_<empty_flag>;

        // Cross: simultaneous write and read
           cross_<write>_<read>: cross cp_<write_en>, cp_<read_en>;

        // Cross: opcode with valid input (verify all ops are tested when valid)
           cross_<opcode>_<valid>: cross cp_<opcode>, cp_<valid_in>;

// UVM Phases Style
// Constructor instantiates the covergroup.
// Build phase creates the TLM port and FIFO.
// Connect phase links the port to the FIFO.
// Run phase uses a forever loop to get items from the FIFO and call cover_group.sample().

    function new(string name = "<DUT_name>_coverage", uvm_component parent = null);
     super.new(name, parent);
     cover_group = new;
    endfunction

    function void build_phase(uvm_phase phase);
     super.build_phase(phase);
     Seq_export = new("Seq_export", this);
     fifo       = new("fifo"      , this);
    endfunction

    function void connect_phase(uvm_phase phase);
     super.connect_phase(phase);
     Seq_export.connect(fifo.analysis_export);
    endfunction

    task run_phase(uvm_phase phase);
      super.run_phase(phase);
      forever begin
       fifo.get(sequence_item);
       cover_group.sample();
      end
    endtask

random_constraints.content:
// Sequence Item Declaration Style
// Input fields should be 'rand bit' or 'rand logic'
// Output fields MUST NOT be 'rand', just 'bit' or 'logic'
// Use UVM macros for all fields to enable printing/copying.

  class <DUT_name>_sequence_item extends uvm_sequence_item;

      // Inputs (Randomized)
      rand bit         <reset_signal>  ;
      rand bit  [31:0] <data_signal>  ;

      // Outputs (NEVER Randomized — updated by monitor)
           bit         <status_signal_1>  ;
           bit  [2:0]  <status_signal_2> ;

      // Computed properties (Not randomized directly)
           bit         <parity_bit>;

     `uvm_object_utils_begin(<DUT_name>_sequence_item)
         `uvm_field_int(<reset_signal> , UVM_ALL_ON)
         `uvm_field_int(<data_signal> , UVM_ALL_ON)
         `uvm_field_int(<status_signal_1> , UVM_ALL_ON)
         `uvm_field_int(<status_signal_2>, UVM_ALL_ON)
         `uvm_field_int(<parity_bit>, UVM_ALL_ON)
     `uvm_object_utils_end

// convert2string Style
// Neatly format inputs and outputs for printing. Use %0b for bits and %0x for data words.

     function string convert2string();
        string s;
        s = super.convert2string();
        s = { s, $sformatf("\n=================================================\n" ) };
        s = { s, $sformatf("  Inputs:\n"                                           ) };
        s = { s, $sformatf("    <reset_signal>  = 'b%0b\n", <reset_signal>                         ) };
        s = { s, $sformatf("    <data_signal>  = 'h%0x\n", <data_signal>                         ) };
        s = { s, $sformatf("  Outputs:\n"                                          ) };
        s = { s, $sformatf("    <status_signal_1>  = 'b%0b\n", <status_signal_1>                         ) };
        s = { s, $sformatf("    <status_signal_2> = 'h%0x\n", <status_signal_2>                        ) };
        s = { s, $sformatf("=================================================\n"   ) };
        return s;
     endfunction

// Global Constraint Style
// Use 'soft' keyword for default behaviors (like keeping reset inactive).
// Use 'inside' to restrict data fields to valid ranges.

        constraint Global_Constraint{
           soft <reset_signal>  == 1'b1;
           <data_signal>  inside { [32'h0000_0000 : 32'hFFFF_FFFF]};
        }

// Reset Constraint Style
// Force reset to active state. Force other control signals to inactive state.

        constraint RESET_Constraint{
           <reset_signal>  == 1'b0;
           <control_signal_1>  == 1'b0; 
           <control_signal_2>   == 1'b0;
        }

// Distribution Constraint Style
// Used for test cases like <Scenario_Name>.
// Use 'dist' to control the probability weighting of signals.

        constraint <Scenario_Name>_Constraint{
           <control_signal_1>  dist   { 1'b1 := 90    , 1'b0 := 10   };
           <control_signal_2>   dist   { 1'b1 := 10    , 1'b0 := 90   };
        }

// Implication Constraints Style (-> and if-else)
// Use to enforce valid protocol relationships and prevent illegal combinations.

        constraint Logical_Relations_Constraint {
           // Using implication operator (->)
           // "If valid is 0, then opcode must be 0"
           (<valid_signal> == 1'b0) -> (<opcode_signal> == 0);

           // Using if-else for mutually exclusive operations
           // "If read_en is 1, write_en must be 0, and vice versa"
           if (<read_enable> == 1'b1) {
               <write_enable> == 1'b0;
           } else {
               // when not reading, write can be anything (or constrained otherwise)
           }
        }

// Solve Before Constraint Style
// Use when the probability of one variable depends on another variable,
// to prevent the solver from skewing the distribution of the independent variable.
// Syntax: solve <independent_var> before <dependent_var>;

        constraint Dependency_Constraint {
           // We want valid to be 1 or 0 with equal probability (50/50).
           // But when valid=1, data can be 4 billion values. When valid=0, data is 0.
           // Without 'solve before', the solver will pick valid=1 99.999% of the time.
           solve <valid_signal> before <data_signal>;

           (<valid_signal> == 1'b0) -> (<data_signal> == 0);
        }

// post_randomize() Function Style
// Use this built-in callback to compute fields that depend on randomized data
// but should NOT be randomized themselves (e.g. Parity, CRC, Checksums).
// This function is automatically called immediately after randomization succeeds.

        function void post_randomize();
            // Compute parity based on the randomized data payload
            // Example: Even parity computation
            <parity_bit> = ^<data_signal>;

            // If you need odd parity, use: ~(^<data_signal>)
        endfunction

// Protocol Control Knobs Style (For Serial Protocols like UART, SPI, I2C)
// When the driver operates cycle-by-cycle, the sequence item must provide 'Knobs'
// (state variables) so the Sequence can easily orchestrate multi-cycle frames.
// Add an enumerated state and constrain the physical protocol pins to it.

        // 1. Declare the Knob (Meta-data, not a real physical pin)
        typedef enum bit [2:0] {PROT_IDLE, PROT_START, PROT_DATA, PROT_STOP} prot_state_e;
        rand prot_state_e cycle_state;

        // 2. Constrain the physical pins based on the Knob
        constraint Protocol_Pins_Constraint {
           (cycle_state == PROT_IDLE)  -> <serial_pin> == 1'b1; // e.g. UART IDLE is high
           (cycle_state == PROT_START) -> <serial_pin> == 1'b0; // e.g. UART START is low
           // For DATA state, the pin can be randomly 0 or 1, or constrained by another knob
        }

assertions.content:
// Assertions Module Header Style
// The assertions module binds to the wrapper RTL So you have all access on Wrapper RTL { bind <DUT_name>_top.<DUT_name>_DUT <DUT_name>_assertions assertion_inst(); }.
// Module name convention: <DUT_name>_assertions

`define DUT <DUT_name>_top.<DUT_name>_DUT
module <DUT_name>_assertions;

  // ... properties, asserts, covers go here ...

endmodule

// Reset Property Style
// |=> is NON-OVERLAPPING: the consequent is sampled ONE clock later.
// Use this only when the RTL reset behavior is synchronous; derive polarity and timing from RTL.
// Check ALL output signals (flags, counters, data outputs) go to their safe default values.

   property check_reset;
   @(posedge `DUT.<clk>)
    (`DUT.<rst> == 0)              // reset asserted (active-low example)
    |=> (`DUT.<flag_out> == 0 && `DUT.<status_out> == <safe_value>);
   endproperty

   assert property ( check_reset ) else $error( "Error in outputs when Reset is asserted" );
   cover  property ( check_reset );

// Flush/Clear Property Style
// Use disable iff(!<rst>) to disable assertion when under reset.
// Use |=> because flush effect is visible NEXT cycle.

   property check_flush;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<flush_signal> == 1)
    |=> (`DUT.<output1> == 0 && `DUT.<output2> == 1);
   endproperty

   assert property ( check_flush ) else $error( "Error in outputs when Flush is asserted" );
   cover  property ( check_flush );

// Flag Implication Property Style
// |-> is OVERLAPPING: antecedent and consequent are sampled on the SAME clock tick.
// Use it for combinational flags only after confirming same-cycle RTL timing.
// Include only reset/flush controls that actually exist in the DUT.

   property <flag>_when_<condition>;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    (`DUT.<condition_signal> == <value>)
    |-> (`DUT.<flag_output> == 1);
   endproperty

   assert property ( <flag>_when_<condition> ) else $error( "<Flag> Flag != 1 when <condition>" );
   cover  property ( <flag>_when_<condition> );

// Counter Increment Property Style
// Use $past() to compare current value against the previous cycle value.
// Use |=> for sequential (next-cycle) effect.
// Disable during reset and flush.

   property counter_increment;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    (!`DUT.<full_flag> && `DUT.<write_en> && !`DUT.<read_en>)
    |=> (`DUT.<counter_out> == $past(`DUT.<counter_out>) + 1);
   endproperty

   assert property ( counter_increment ) else $error( "Error in counter increment" );
   cover  property ( counter_increment );

// Counter Decrement Property Style

   property counter_decrement;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    (!`DUT.<empty_flag> && !`DUT.<write_en> && `DUT.<read_en>)
    |=> (`DUT.<counter_out> == $past(`DUT.<counter_out>) - 1);
   endproperty

   assert property ( counter_decrement ) else $error( "Error in counter decrement" );
   cover  property ( counter_decrement );

// Mutex (Mutual Exclusion) Property Style
// Two outputs that can never be simultaneously high.
// Use 'not' keyword to express the forbidden state.

   property <signalA>_<signalB>_mutex;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    not (`DUT.<signalA> == 1 && `DUT.<signalB> == 1);
   endproperty

   assert property ( <signalA>_<signalB>_mutex ) else $error( "Both <signalA> and <signalB> cannot be high simultaneously" );
   cover  property ( <signalA>_<signalB>_mutex );

// Boundary Condition Property Style
// Checks that a forbidden operation does not corrupt state.
// Use |-> for immediate implication (same clock cycle).

   property no_<op>_when_<boundary>;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    (`DUT.<boundary_flag> && `DUT.<op_signal> && !`DUT.<other_op>)
    |-> (`DUT.<state_output> == <boundary_value>);
   endproperty

   assert property ( no_<op>_when_<boundary> ) else $error( "State corruption on <op> when <boundary>" );
   cover  property ( no_<op>_when_<boundary> );

// Simultaneous Operations Property Style
// When both write and read happen together, net state stays the same.
// Use $past() to compare current vs previous value.

   property simultaneous_<write>_<read>;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst> || `DUT.<flush>)
    (`DUT.<read_en> && `DUT.<write_en> && !`DUT.<full_flag> && !`DUT.<empty_flag>)
    |=> (`DUT.<counter_out> == $past(`DUT.<counter_out>));
   endproperty

   assert property ( simultaneous_<write>_<read> ) else $error( "State changed unexpectedly on simultaneous ops" );
   cover  property ( simultaneous_<write>_<read> );

// File Structure Style — always follow this exact order:

`define DUT <name>_top.<name>_DUT
module <name>_assertions;

  // properties
     property prop_one;
     @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
      <antecedent>
      |=> <consequent>;
     endproperty

     property prop_two;
     // ...
     endproperty

  // assert property
     assert property (  prop_one  ) else $error( "Descriptive error message here"    );
     assert property (  prop_two  ) else $error( "Another descriptive message"        );

  // cover property
     cover property (  prop_one  );
     cover property (  prop_two  );

endmodule

// IMPORTANT FORMATTING RULES:
// 1. assert/cover lines are aligned: property name is padded to consistent width
// 2. $error messages are also right-aligned for readability
// 3. Two blank lines separate the properties block from assert/cover blocks
// 4. Each property has exactly one blank line after its endproperty

// |-> vs |=> Decision Guide — CRITICAL: wrong choice = wrong assertion
//
// Use |-> (immediate implication, SAME clock cycle) when:
//   - Consequent is COMBINATIONAL: driven by 'assign' or 'always_comb' in RTL.
//   - The output changes in the SAME cycle as the condition.
//   Example: assign full = (count == MAX);  -> flag is combinational -> use |->
//
// Use |=> (next-cycle implication) when:
//   - Consequent is REGISTERED: driven by 'always_ff @(posedge clk)' in RTL.
//   - The output changes on the NEXT clock edge after the condition.
//   Example: always_ff @(posedge clk) count <= count + 1;  -> use |=>
//
// RULE: Grep the RTL for the output signal. Is it in always_ff? -> |=>
//                                             Is it an assign?  -> |->

   // Registered output (always_ff) — use |=>
   property registered_output_check;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<write_en> == 1)
    |=> (`DUT.<registered_output> == $past(`DUT.<data_in>));
   endproperty

   // Combinational output (assign/always_comb) — use |->
   property combinational_flag_check;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<counter> == `DUT.<MAX_VALUE>)
    |-> (`DUT.<full_flag> == 1);
   endproperty

   assert property ( registered_output_check  ) else $error( "Registered output mismatch"       );
   assert property ( combinational_flag_check  ) else $error( "Combinational flag mismatch"      );
   cover  property ( registered_output_check  );
   cover  property ( combinational_flag_check  );

// Sequential Temporal Assertions — ## Operator
// Use ## to express 'after exactly N clock cycles'.
// ##1 = next clock cycle, ##N = after N cycles, ##[1:N] = within 1 to N cycles.
// Essential for protocols (UART, SPI, I2C) where effects span multiple cycles.

   // Example 1: After valid is asserted, ready must respond within 1-4 cycles
   property handshake_response;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    ($rose(`DUT.<valid>))
    |-> ##[1:4] (`DUT.<ready> == 1);
   endproperty

   // Example 2: After start bit (TX falls), busy must be asserted 1 cycle later
   property busy_after_start_bit;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    ($fell(`DUT.<tx_out>))
    |=> (`DUT.<busy> == 1);
   endproperty

   // Example 3: For a 2-stage pipeline: output reflects input from 2 cycles ago
   property pipeline_output_correct;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<valid_in> == 1)
    |-> ##2 (`DUT.<result_out> == $past(`DUT.<data_in>, 2));
   endproperty

   assert property ( handshake_response       ) else $error( "Handshake: ready not received within 4 cycles" );
   assert property ( busy_after_start_bit      ) else $error( "busy not asserted after start bit"             );
   assert property ( pipeline_output_correct   ) else $error( "Pipeline output does not match delayed input"  );
   cover  property ( handshake_response       );
   cover  property ( busy_after_start_bit      );
   cover  property ( pipeline_output_correct   );

// Edge Detection Assertions — $rose(), $fell(), $stable(), $past()
//   $rose(sig)    : true when sig transitions 0->1 at this clock edge
//   $fell(sig)    : true when sig transitions 1->0 at this clock edge
//   $stable(sig)  : true when sig has NOT changed from previous clock edge
//   $past(sig)    : value of sig exactly ONE clock cycle ago
//   $past(sig, N) : value of sig exactly N clock cycles ago
//
// Use when: protocol has edge-triggered conditions, or data must be stable around an edge.

   // Example 1: When done rises, output data must be valid and stable
   property output_valid_on_done;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    $rose(`DUT.<done_sig>)
    |-> (`DUT.<data_out_valid> == 1 && $stable(`DUT.<data_out>));
   endproperty

   // Example 2: Busy must stay high until done — no glitching allowed
   property busy_stable_during_transfer;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<busy> == 1 && !$rose(`DUT.<done_sig>))
    |=> ($stable(`DUT.<busy>) || `DUT.<busy> == 1);
   endproperty

   // Example 3: TX output data bit must match the stored shift register value
   property serial_bit_matches_data;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<state> == DATA)
    |-> (`DUT.<tx_out> == `DUT.<shift_reg>[`DUT.<bit_counter>]);
   endproperty

   assert property ( output_valid_on_done      ) else $error( "Data not valid when done asserted"        );
   assert property ( busy_stable_during_transfer) else $error( "Busy glitched during active transfer"     );
   assert property ( serial_bit_matches_data    ) else $error( "TX bit does not match shift register bit" );
   cover  property ( output_valid_on_done      );
   cover  property ( busy_stable_during_transfer);
   cover  property ( serial_bit_matches_data    );

// Data Path Integrity Assertions
// Verify the CORRECTNESS of output data values, not just their timing.
// Use $past(signal, N) when the DUT has pipeline stages (output is delayed by N cycles).
//
// Key insight: A flag assertion checks WHEN a signal is high.
//              A data assertion checks WHAT VALUE the signal carries.
// Both are necessary for complete verification.

   // Example 1: Parity output must match computed parity of data
   property parity_correct;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<state> == PARITY)
    |-> (`DUT.<tx_out> == ^$past(`DUT.<data_in>, 2));
   endproperty

   // Example 2: After a write, reading back must return the same data
   property read_after_write_correct;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    ($rose(`DUT.<read_en>) && $past(`DUT.<write_en>))
    |=> (`DUT.<data_out> == $past(`DUT.<data_in>, 2));
   endproperty

   // Example 3: ALU addition result must be arithmetically correct
   property alu_add_result;
   @(posedge `DUT.<clk>) disable iff(!`DUT.<rst>)
    (`DUT.<opcode> == ADD && `DUT.<valid_in>)
    |=> (`DUT.<result> == ($past(`DUT.<op_a>) + $past(`DUT.<op_b>)));
   endproperty

   assert property ( parity_correct          ) else $error( "Parity bit computed incorrectly"         );
   assert property ( read_after_write_correct ) else $error( "Read-after-write data mismatch"          );
   assert property ( alu_add_result           ) else $error( "ALU addition result is incorrect"        );
   cover  property ( parity_correct          );
   cover  property ( read_after_write_correct );
   cover  property ( alu_add_result           );

// Assertion Checklist — Before writing a property:
// 1. Is the signal internal or interface? (Bind if internal)
